contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // 1. Restrict to admissible domain: msg.value > 0 so the transfer matters
        amount = bound(amount, 1, type(uint256).max);

