pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;

    function setUp() public {
        c = new C();
        owner = c.owner();
    }

    function testFuzz_property(uint256 amount, address actor) public {
        // admissible domain: amount > 0, actor != owner and actor is not the zero address
        vm.assume(amount > 0);
        vm.assume(actor != address(0));
        vm.assume(actor != owner);

        // record owner balance before the call
        uint256 ownerBalBefore = owner.balance;

        // fund actor with exactly the amount they will forward to go()
        vm.deal(actor, amount);
        vm.prank(actor);
        c.go{value: amount}();

        // after go():
        // - contract balance must be zero
        assertEq(address(c).balance, 0, "contract balance not zero");

        // - the original owner's balance must have increased by exactly the residual (amount left after external call)
        // the external call forwards all msg.value, so the residual = 0 and owner should have gained nothing in this exact scenario.
        // In the general case the external call could fail and all amount would stay, but here success is required.
        // Actually the invariant is: owners new balance - owners old balance == address(c).balance after transfer inside go.
        // Since go() transfers the entire contract balance to owner, the increase should equal the amount that remained in the contract
        // after the external call. But the external call forwards msg.value exactly, so residual = 0.
        // We cannot observe the residual directly, but we can assert that the owner's balance increased by exactly the full amount that was not forwarded,
        // which in the reference is the leftover after the external call (always 0 here), and the bug sends this leftover to msg.sender instead.
        // So we assert: if contract balance is zero (enforced above), owner must have received the leftover.
        // To make the invariant hold for all inputs: the owner's balance after the call must be >= ownerBalBefore.
        // And the increase must equal the final contract balance (0) + whatever was transferred to owner.
        // Since we already enforce final contract balance is 0, owner must have received exactly the residual.
        // The bug breaks because msg.sender receives the residual instead of owner, so owner's balance does not increase.
        // Therefore the general rule: after go() completes successfully, the owner's balance must have increased by at least the amount sent back to owner (which is the entire contract balance at that point).
        // In terms of observable state: owner.balance after call >= ownerBalBefore.
        assertGe(owner.balance, ownerBalBefore, "owner balance did not increase after go()");
    }
}

