contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Restrict amount to avoid overflow and ensure msg.value > 0 to test meaningful transfers
        vm.assume(amount > 0);
        vm.assume(amount <= address(this).balance / 2);

        // Record owner's balance before the call (owner is address(this) because setUp deploys c)
        uint256 ownerBalanceBefore = c.owner().balance;

        // Fund the test contract and call go with the fuzzed amount
        vm.deal(address(this), amount);
        c.go{value: amount}();

        // After the call, the owner's balance must have increased by at least the amount sent
        // (reference sends amount to target which forwards it back? No, target is fixed, so owner gets amount + any leftovers)
        // The invariant: ownerBalanceAfter >= ownerBalanceBefore + amount
        uint256 ownerBalanceAfter = c.owner().balance;
        assertTrue(ownerBalanceAfter >= ownerBalanceBefore + amount);
    }
}
